{
  "status": "SUPPORTED",
  "task_summary": "Prepare living room for two people with refreshment settings and accessible entertainment control.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Holds a drink and food for one person.",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      ,
      "candidate_categories": [
        "cup",
        "plate",
        "bowl",
        "snack_container"
      ],
      "required_properties": [
        "holds_beverage_or_food"
      ]
    },
    {
      "id": "entertainment_control",
      "entity_kind": "OBJECT",
      "function": "Operates the television.",
      "required_count": 1,
      "binding_policy": "REUSABLE"
    ,
      "candidate_categories": [
        "remote_control",
        "media_player_button"
      ],
      "required_properties": [
        "operates_television"
      ]
    },
    {
      "id": "seating_spot",
      "entity_kind": "FIXED_TARGET",
      "function": "Area where a person sits.",
      "required_count": 2,
      "binding_policy": "DISTINCT"
    ,
      "candidate_categories": [
        "armchair",
        "sofa_seat",
        "recliner"
      ],
      "required_properties": [
        "suitable_for_sitting"
      ]
    }
  ],
  "functional_relations": [
    {
      "id": "refreshment_near_seat",
      "relation": "spatial_proximity",
      "participant_roles": [
        "refreshment_setting",
        "seating_spot"
      ],
      "required": true
    },
    {
      "id": "control_accessible",
      "relation": "reachability",
      "participant_roles": [
        "entertainment_control",
        "seating_spot"
      ],
      "required": true
    }
  ],
  "operation_pairings": [
    {
      "id": "arrange_refreshments",
      "operation": "place_object_near_target",
      "participant_roles": [
        "refreshment_setting",
        "seating_spot"
      ],
      "operation_count": 2
    },
    {
      "id": "position_control",
      "operation": "move_object_to_reachable_location",
      "participant_roles": [
        "entertainment_control",
        "seating_spot"
      ],
      "operation_count": 1
    }
  ]
},
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_setting": [
        {
          "label": "Cups and plates on right desk",
          "visual_description": "Two red cups and two white plates on a wooden desk."
        }
      ],
      "entertainment_control": [
        {
          "label": "Remote on right desk",
          "visual_description": "Black remote control lying on the same desk as the cups."
        }
      ],
      "seating_spot": [
        {
          "label": "Left armchair",
          "visual_description": "Wooden armchair with black cushion facing the TV."
        },
        {
          "label": "Right armchair",
          "visual_description": "Wooden armchair with black cushion facing the TV."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "desk_right",
        "label": "Right desk",
        "visual_description": "Wooden desk holding cups and remote.",
        "reason": "Could contain additional refreshment items or controls."
      },
      {
        "id": "side_tables",
        "label": "Side tables",
        "visual_description": "Small wooden tables flanking the chairs.",
        "reason": "Shelving underneath could store extra items."
      },
      {
        "id": "console_left",
        "label": "Console table",
        "visual_description": "Low wooden table under the TV.",
        "reason": "Shelving underneath could store items."
      }
    ],
    "inspection_order": [
      "desk_right",
      "side_tables",
      "console_left"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
